// Compiler is free to reorder these (same observable behavior):
int x = 0, y = 0;
x = 5;        // Statement 1
y = 10;       // Statement 2  
// May execute as: y=10; x=5; or even in parallel!

// Sequence points occur at:
// - End of each full expression/statement
// - Before function call after args evaluated  
// - After return value computed
// But sequence points only constrain single-threaded behavior!

// Example of problematic reordering in multithreading:
pInstance = new Singleton;  // Source code order
// Compiler may generate:
pInstance = operator new(sizeof(Singleton));  // Step 1 & 3
new (pInstance) Singleton;                    // Step 2
// Steps 3 and 2 are swapped!

// Memory barriers prevent reordering (platform-specific):
asm volatile("mfence" ::: "memory");  // x86 full barrier
asm volatile("" ::: "memory");         // Compiler barrier only

// C++11 atomics provide portable memory ordering:
std::atomic<int> x;
x.store(5, std::memory_order_release);  // Release semantics
int y = x.load(std::memory_order_acquire);  // Acquire semantics

