#include <iostream>
#include <thread>
#include <atomic>

// Demonstrates instruction reordering effects

class ReorderingDemo {
public:
    // Without atomics: compiler/hardware can reorder
    int data = 0;
    bool ready = false;

    // With atomics: ordering is controlled
    std::atomic<int> data_atomic{0};
    std::atomic<bool> ready_atomic{false};

    // Producer (without atomics) - UNSAFE
    void produceUnsafe() {
        data = 42;           // Step 1
        ready = true;        // Step 2
        // Compiler/hardware MAY reorder these!
        // Consumer might see ready=true but data=0
    }

    // Consumer (without atomics) - UNSAFE  
    void consumeUnsafe() {
        if (ready) {         // May see reordered writes
            std::cout << "Data (unsafe): " << data << "\n";
            // Might print 0 instead of 42!
        }
    }

    // Producer (with atomics) - SAFE
    void produceSafe() {
        data_atomic.store(42, std::memory_order_relaxed);
        // Release: all prior writes visible before this write
        ready_atomic.store(true, std::memory_order_release);
    }

    // Consumer (with atomics) - SAFE
    void consumeSafe() {
        // Acquire: all subsequent reads happen after this read
        if (ready_atomic.load(std::memory_order_acquire)) {
            std::cout << "Data (safe): " 
                     << data_atomic.load(std::memory_order_relaxed) 
                     << "\n";
            // Guaranteed to see 42
        }
    }
};

int main() {
    std::cout << "Instruction Reordering Demo\n\n";

    std::cout << "Key insight: C++ abstract machine is single-threaded.\n";
    std::cout << "Compilers optimize assuming single-threaded execution.\n";
    std::cout << "Operations can be reordered if single-thread behavior\n";
    std::cout << "appears unchanged, breaking multithreaded code!\n\n";

    ReorderingDemo demo;

    // Safe example with proper synchronization
    std::thread producer(&ReorderingDemo::produceSafe, &demo);
    std::thread consumer(&ReorderingDemo::consumeSafe, &demo);

    producer.join();
    consumer.join();

    std::cout << "\nUse atomics with proper memory_order to control\n";
    std::cout << "instruction reordering in multithreaded code.\n";
    std::cout << "\nCommon memory orderings:\n";
    std::cout << "  - relaxed: No ordering constraints\n";
    std::cout << "  - acquire: Prevents subsequent ops from moving before\n";
    std::cout << "  - release: Prevents prior ops from moving after\n";
    std::cout << "  - seq_cst: Sequentially consistent (strongest)\n";

    return 0;
}
